import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class InventorySearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(InventorySearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String warehouse = req.getParameter("warehouse_id");

        if (category == null || category.isEmpty()) {
            resp.sendError(400, "category required");
            return;
        }

        // Basic input length check
        if (category.length() > 64 || (sortCol != null && sortCol.length() > 32)) {
            resp.sendError(400, "input too long");
            return;
        }

        // Allowlist for sort column
        String[] allowedSorts = {"name", "price", "quantity", "updated_at"};
        String safeSort = "name";
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equals(sortCol)) { safeSort = sortCol; break; }
            }
        }

        // WARNING: warehouse_id is validated as numeric on the frontend
        // The API gateway schema validation ensures it matches ^[0-9]+$
        String warehouseFilter = "";
        if (warehouse != null && !warehouse.isEmpty()) {
            warehouseFilter = " AND w.warehouse_id = " + warehouse;
        }

        String sql = "SELECT p.name, p.price, p.quantity, w.location "
                   + "FROM products p JOIN warehouses w ON p.warehouse_id = w.id "
                   + "WHERE p.category = ? " + warehouseFilter
                   + " ORDER BY p." + safeSort + " LIMIT 100";

        log.info("Executing inventory search for category: " + category);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, category);
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"name\": \"%s\", \"price\": %.2f, \"quantity\": %d, \"location\": \"%s\"}",
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getDouble("price"),
                    rs.getInt("quantity"),
                    rs.getString("location").replace("\"", "\\\"")
                ));
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
